ST.html:p:
IF FirstScan THEN
    LOOP_4750_03_TRIP   := TRUE;
    LOOP_4712_02_TRIP   := TRUE;
    LOOP_104_01_TRIP    := TRUE;
    SAFE_STATE          := TRUE;
    TV_4750_03_Out      := 6554;
    PVA_4712_02_Out     := 6554;
    FC_VALVE_H_1007_Out := 6554;
    SV_104_01_Out       := FALSE;
    FirstScan           := FALSE;
    RETURN;
END_IF;

PI_4712_01_Scaled := ((INT_TO_REAL(PI_4712_01_Raw) - 6554.0) /
                      (32767.0 - 6554.0)) * 200.0;

IF PI_4712_01_Scaled >= PI_4712_01_HH_SP THEN
    PI_4712_01_HH_Latch.S1 := TRUE;
ELSIF PI_4712_01_Scaled <= (PI_4712_01_HH_SP - PI_4712_01_Deadband) THEN
    PI_4712_01_HH_Latch.S1 := FALSE;
END_IF;
PI_4712_01_HH_Latch.R := PI_4712_01_HH_Ack AND NOT (PI_4712_01_Scaled >= PI_4712_01_HH_SP);
PI_4712_01_HH_Latch(S1 := PI_4712_01_HH_Latch.S1, R := PI_4712_01_HH_Latch.R);

IF PI_4712_01_Scaled >= PI_4712_01_H_SP THEN
    PI_4712_01_H := TRUE;
ELSIF PI_4712_01_Scaled <= (PI_4712_01_H_SP - PI_4712_01_Deadband) THEN
    PI_4712_01_H := FALSE;
END_IF;

IF PI_4712_01_Scaled <= PI_4712_01_L_SP THEN
    PI_4712_01_L := TRUE;
ELSIF PI_4712_01_Scaled >= (PI_4712_01_L_SP + PI_4712_01_Deadband) THEN
    PI_4712_01_L := FALSE;
END_IF;

IF PI_4712_01_Scaled <= PI_4712_01_LL_SP THEN
    PI_4712_01_LL_Latch.S1 := TRUE;
ELSIF PI_4712_01_Scaled >= (PI_4712_01_LL_SP + PI_4712_01_Deadband) THEN
    PI_4712_01_LL_Latch.S1 := FALSE;
END_IF;
PI_4712_01_LL_Latch.R := PI_4712_01_LL_Ack AND NOT (PI_4712_01_Scaled <= PI_4712_01_LL_SP);
PI_4712_01_LL_Latch(S1 := PI_4712_01_LL_Latch.S1, R := PI_4712_01_LL_Latch.R);

PICSA_4712_02_HH := PI_4712_01_HH_Latch.Q1;
PICSA_4712_02_LL := PI_4712_01_LL_Latch.Q1;

TICSA_4750_03_HH := HS_4750_01;
TICSA_4750_03_LL := FALSE;
SV_104_01_HH     := FALSE;
SV_104_01_LL     := FALSE;

IF TICSA_4750_03_HH OR TICSA_4750_03_LL THEN
    LOOP_4750_03_TRIP := TRUE;
ELSIF LOOP_4750_03_TRIP AND MANUAL_RESET
      AND NOT TICSA_4750_03_HH AND NOT TICSA_4750_03_LL THEN
    LOOP_4750_03_TRIP := FALSE;
END_IF;

IF PICSA_4712_02_HH OR PICSA_4712_02_LL THEN
    LOOP_4712_02_TRIP := TRUE;
ELSIF LOOP_4712_02_TRIP AND MANUAL_RESET
      AND NOT PICSA_4712_02_HH AND NOT PICSA_4712_02_LL THEN
    LOOP_4712_02_TRIP := FALSE;
END_IF;

IF SV_104_01_HH OR SV_104_01_LL THEN
    LOOP_104_01_TRIP := TRUE;
ELSIF LOOP_104_01_TRIP AND MANUAL_RESET
      AND NOT SV_104_01_HH AND NOT SV_104_01_LL THEN
    LOOP_104_01_TRIP := FALSE;
END_IF;

SAFE_STATE := ESTOP
              OR LOOP_4750_03_TRIP
              OR LOOP_4712_02_TRIP
              OR LOOP_104_01_TRIP;

IF NOT SAFE_STATE THEN

    TV_4750_03_Error    := TV_4750_03_SP - PI_4712_01_Scaled;
    TV_4750_03_Integral := TV_4750_03_Integral + (TV_4750_03_Ki * TV_4750_03_Error);
    IF TV_4750_03_Integral > 100.0 THEN
        TV_4750_03_Integral := 100.0;
    ELSIF TV_4750_03_Integral < 0.0 THEN
        TV_4750_03_Integral := 0.0;
    END_IF;
    TV_4750_03_Output_Pct := (TV_4750_03_Kp * TV_4750_03_Error) + TV_4750_03_Integral;
    IF TV_4750_03_Output_Pct > 100.0 THEN
        TV_4750_03_Output_Pct := 100.0;
    ELSIF TV_4750_03_Output_Pct < 0.0 THEN
        TV_4750_03_Output_Pct := 0.0;
    END_IF;
    TV_4750_03_Out := REAL_TO_INT(6554.0 + (TV_4750_03_Output_Pct / 100.0) * (32767.0 - 6554.0));

    PVA_4712_02_Error    := PVA_4712_02_SP - PI_4712_01_Scaled;
    PVA_4712_02_Integral := PVA_4712_02_Integral + (PVA_4712_02_Ki * PVA_4712_02_Error);
    IF PVA_4712_02_Integral > 100.0 THEN
        PVA_4712_02_Integral := 100.0;
    ELSIF PVA_4712_02_Integral < 0.0 THEN
        PVA_4712_02_Integral := 0.0;
    END_IF;
    PVA_4712_02_Output_Pct := (PVA_4712_02_Kp * PVA_4712_02_Error) + PVA_4712_02_Integral;
    IF PVA_4712_02_Output_Pct > 100.0 THEN
        PVA_4712_02_Output_Pct := 100.0;
    ELSIF PVA_4712_02_Output_Pct < 0.0 THEN
        PVA_4712_02_Output_Pct := 0.0;
    END_IF;
    PVA_4712_02_Out := REAL_TO_INT(6554.0 + (PVA_4712_02_Output_Pct / 100.0) * (32767.0 - 6554.0));

    FC_1007_Error    := FC_1007_SP - PI_4712_01_Scaled;
    FC_1007_Integral := FC_1007_Integral + (FC_1007_Ki * FC_1007_Error);
    IF FC_1007_Integral > 100.0 THEN
        FC_1007_Integral := 100.0;
    ELSIF FC_1007_Integral < 0.0 THEN
        FC_1007_Integral := 0.0;
    END_IF;
    FC_1007_Output_Pct := (FC_1007_Kp * FC_1007_Error) + FC_1007_Integral;
    IF FC_1007_Output_Pct > 100.0 THEN
        FC_1007_Output_Pct := 100.0;
    ELSIF FC_1007_Output_Pct < 0.0 THEN
        FC_1007_Output_Pct := 0.0;
    END_IF;
    FC_VALVE_H_1007_Out := REAL_TO_INT(6554.0 + (FC_1007_Output_Pct / 100.0) * (32767.0 - 6554.0));

    SV_104_01_Out           := NOT HS_4750_01;
    CHECK_75SA21_Out        := TRUE;
    CHECK_P_4711_Out        := TRUE;
    BV_73KH12_50_1_Out      := TRUE;
    BV_73KH12_50_2_Out      := TRUE;
    BV_73KH12_25_1_Out      := TRUE;
    BV_73KH12_25_2_Out      := TRUE;
    BV_MNc_47125_N5_Out     := TRUE;
    BV_MNc_47125_73HG12_Out := TRUE;
    BV_MNc_47127_Q80_Out    := TRUE;

ELSE
    TV_4750_03_Out          := 6554;
    PVA_4712_02_Out         := 6554;
    FC_VALVE_H_1007_Out     := 6554;
    SV_104_01_Out           := FALSE;
    CHECK_75SA21_Out        := FALSE;
    CHECK_P_4711_Out        := FALSE;
    BV_73KH12_50_1_Out      := FALSE;
    BV_73KH12_50_2_Out      := FALSE;
    BV_73KH12_25_1_Out      := FALSE;
    BV_73KH12_25_2_Out      := FALSE;
    BV_MNc_47125_N5_Out     := FALSE;
    BV_MNc_47125_73HG12_Out := FALSE;
    BV_MNc_47127_Q80_Out    := FALSE;
    TV_4750_03_Integral     := 0.0;
    PVA_4712_02_Integral    := 0.0;
    FC_1007_Integral        := 0.0;
END_IF;

System_Alarm :=
    PI_4712_01_HH_Latch.Q1 OR PI_4712_01_LL_Latch.Q1 OR
    PI_4712_01_H            OR PI_4712_01_L            OR
    LOOP_4750_03_TRIP       OR LOOP_4712_02_TRIP        OR
    LOOP_104_01_TRIP        OR SAFE_STATE;
